INSERT INTO services (slug,title,summary,description,image,sort_order) VALUES ('live-sports','Live Sports Viewing','Every big match on big screens.','Watch top football leagues and other sports live, in a comfortable, air-conditioned space. 18+ only.','https://images.unsplash.com/photo-1508098682722-e99c43a406b2?auto=format&fit=crop&w=1600&q=80',0);
INSERT INTO services (slug,title,summary,description,image,sort_order) VALUES ('customer-support','Customer Support','Friendly help in every shop.','Our trained staff help with account questions, rules and responsible-gambling tools.','https://images.unsplash.com/photo-1574629810360-7efbbe195018?auto=format&fit=crop&w=1600&q=80',1);
INSERT INTO services (slug,title,summary,description,image,sort_order) VALUES ('become-an-agent','Become an Agent','Open a shop with us.','Training, branding and ongoing support for approved agents. Subject to our checks and the regulator''s requirements.','https://images.unsplash.com/photo-1517466787929-bc90951d0974?auto=format&fit=crop&w=1600&q=80',2);
INSERT INTO services (slug,title,summary,description,image,sort_order) VALUES ('responsible-gambling','Responsible Gambling','Play safe. Know your limits.','Set limits, take breaks or self-exclude. Ask our staff for help, and seek support if gambling is causing you problems.','https://images.unsplash.com/photo-1579952363873-27f3bade9f55?auto=format&fit=crop&w=1600&q=80',3);
